let language='en';const original=new WeakMap(),shown=new WeakMap(),attrs=['placeholder','title','aria-label'];
function piece(text){const t=text.trim();if(!t)return text;if(Object.hasOwn(es,t))return text.replace(t,es[t]);for(const [re,to] of patterns)if(re.test(t))return text.replace(t,t.replace(re,to));return null;}
function translate(text){if(language!=='es'||!/[A-Za-z]/.test(text))return text;const t=text.trim();if(Object.hasOwn(es,t))return text.replace(t,es[t]);
 if(text.includes(' · '))return text.split(' · ').map(p=>piece(p)??p).join(' · ');return piece(text)??text;}
function textNode(node){const current=node.data;if(!original.has(node)||shown.get(node)!==current)original.set(node,current);const next=translate(original.get(node));shown.set(node,next);if(next!==current)node.data=next;}
function element(el){for(const name of attrs){if(!el.hasAttribute(name))continue;const key='i18n:'+name,value=el.getAttribute(name);if(el[key+':shown']!==value)el[key]=value;const next=translate(el[key]);el[key+':shown']=next;if(next!==value)el.setAttribute(name,next);}}
function walk(root){if(skip(root))return;if(root.nodeType===3){if(!['SCRIPT','STYLE'].includes(root.parentNode?.tagName))textNode(root);return;}if(root.nodeType!==1&&root.nodeType!==9&&root.nodeType!==11)return;if(['SCRIPT','STYLE'].includes(root.tagName))return;if(root.nodeType===1)element(root);if(root.tagName==='TEXTAREA')return;for(const c of root.childNodes)walk(c);}
// Chat messages, names and poll questions come from viewers and streamers and stay untouched.
const skip=node=>{const el=node.nodeType===1?node:node.parentElement;return !!el?.closest?.('[data-i18n-skip],#messages > *,.chat-row');};
let observer=null;
function setLanguage(next){language=next==='es'?'es':'en';document.documentElement.lang=language;
 if(!observer&&typeof MutationObserver!=='undefined'){observer=new MutationObserver(list=>{for(const m of list){if(m.type==='characterData'){if(!skip(m.target))textNode(m.target);}else if(m.type==='attributes'){if(!skip(m.target))element(m.target);}else for(const n of m.addedNodes)if(!skip(n))walk(n);}});observer.observe(document.documentElement,{subtree:true,childList:true,characterData:true,attributes:true,attributeFilter:attrs});}
 walk(document.body);if(document.title)document.title=translate(document.title.replace(/^Bubblecast Estudio$/,'Bubblecast Studio'));}
window.bubblecastI18n={setLanguage,translate,get language(){return language;}};
